    type: "dammy",
    desc: `Ta xuyên không thành sư tôn của Vô Tình đạo, giờ đây đang vô cùng hoảng loạn.

Là môn phái có tỷ lệ độc thân cao nhất, lại là nghề nghiệp nguy hiểm bậc nhất trong giới xuyên sách là sư tôn, ta lúc nào cũng lo sợ cho tính mạng của mình.

May mắn thay ta chỉ là một nhân vật phụ, chỉ cần im lặng làm người qua đường là được.

Kết quả đêm hôm đó, ta gặp một giấc mơ kỳ lạ.

Đồ đệ tự tay ta nuôi dưỡng trèo lên giường ta, hỏi ta có muốn cùng hắn song tu hay không.

Ta chết lặng.

Sao ta lại quên mất đồ đệ cũng là một chức nghiệp nguy hiểm chứ.
`
